dict(s='neoconservadorismo', n='Neoconservadorismo', f=C, x=85, y=62, r='Conservadorismo com política externa ativa para espalhar a democracia.', i='Nascido nos EUA com ex-esquerdistas desiludidos. Defende valores ocidentais, Estado forte na segurança e uso do poder militar no exterior.', e='Forte em defesa.', m='Pró-mercado, aceitando algum Estado social.', d='Defende a democracia, com menos ênfase em liberdades civis na guerra ao terror.', q='Não é prioridade.', p='Irving Kristol, Norman Podhoretz.', h='Governo George W. Bush e a Guerra do Iraque, em 2003.', b='Influência pequena; aparece no alinhamento com os EUA.', pa=[], fi=[], c='A Guerra do Iraque é o principal argumento contra: democracia imposta de fora costuma falhar.', w='Neoconservadorismo', forte=['Leva a sério a ameaça de regimes autoritários.', 'Critica relativismo diante de ditaduras.'], contra=['Quer espalhar democracia pela guerra.', 'Desconfia de grandes planos sociais internos e aposta em refazer países inteiros.'], apelo=False),
dict(s='direita-radical', n='Direita radical', f=C, x=62, y=84, r='Aceita o voto, mas tensiona a democracia liberal.', i='Combina nacionalismo, autoridade e populismo. Cientistas políticos como Cas Mudde a distinguem da extrema-direita, que rejeita a democracia em si.', e='Forte, com foco em lei e ordem.', m='Varia, muitas vezes protecionista.', d='Disputa imprensa, tribunais e direitos de minorias.', q='Valoriza a maioria nacional.', p='Estudada por Cas Mudde e Michael Minkenberg.', h='Orbán na Hungria, Rassemblement National na França e Trump nos EUA são frequentemente citados.', b='Parte do debate sobre o bolsonarismo e a direita atual.', pa=[], fi=['Nikolas Ferreira', 'Eduardo Bolsonaro'], c='Mesmo eleita, pode enfraquecer os freios democráticos aos poucos.', w='Extrema-direita', wl='Wikipédia: Extrema-direita', forte=['Dá voz a insatisfações que partidos tradicionais ignoraram.', 'Aponta falhas reais de elites e burocracias.'], contra=['Defende a soberania do povo, mas limita tribunais e imprensa que protegem esse povo.', 'Critica elites e costuma ter líderes muito ricos.'], apelo=False),
dict(s='bolsonarismo', n='Bolsonarismo', f=C, x=85, y=75, r='Movimento em torno de Jair Bolsonaro: conservador, antipetista e armamentista.', i='Une costumes conservadores, pauta de segurança e armas, agenda liberal na economia e oposição ao PT e ao STF, com forte presença nas redes. Inclui correntes moderadas e radicais.', e='Duro em segurança; desconfia de STF e TSE.', m='Agenda liberal sob Paulo Guedes, com concessões pragmáticas.', d='Fala em liberdade de expressão; críticos veem ataques a instituições.', q='Rejeita políticas identitárias.', p='Influência de Olavo de Carvalho; estudado por Marcos Nobre e Isabela Kalil.', h='Eleição de 2018, governo de 2019 a 2022 e atos de 8 de janeiro de 2023.', b='É um fenômeno brasileiro, hoje com Flávio e Michelle Bolsonaro entre as lideranças.', pa=['pl'], fi=['Jair Bolsonaro', 'Flávio Bolsonaro', 'Nikolas Ferreira', 'Olavo de Carvalho'], c='O STF condenou Bolsonaro e aliados por tentativa de golpe, e os checadores registram muitas falas falsas. Defensores falam em perseguição.', w='Bolsonarismo', forte=['Representa uma parcela grande da população conservadora e reacionária do país, que antes não se via em nenhum partido.', 'Deu voz a quem se sentia excluído do debate público.', 'Pôs a insegurança pública no centro.', 'Mobilizou eleitores religiosos e conservadores antes ignorados.'], contra=['Fala contra a “velha política” e governou com o Centrão.', 'Diz defender a verdade e adotou uma estratégia de vale-tudo, com uso intenso de sofismos e notícias falsas: seu líder encabeça o ranking de falas falsas da Lupa.', 'Fala em liberdade e é considerado, por cientistas e jornalistas, contrário à ciência e à liberdade de imprensa, como na pandemia e nos ataques a repórteres.', 'Chama-se patriota e tornou-se muito ligado a uma visão entreguista, de favorecimento dos Estados Unidos, com parte de suas lideranças apoiando pressões e tarifas americanas contra o Brasil em 2025.', 'Diz defender a democracia e questiona constantemente as urnas, as eleições e as instituições que a garantem; o líder foi condenado pelo STF e está preso por articular uma tentativa de golpe de Estado.', 'Defende a liberdade e tolerou pedidos de intervenção militar.', 'Critica corrupção e foi alvo de escândalos como o das joias.'], apelo=False),
dict(s='lulismo', n='Lulismo', f=R, x=-30, y=8, r='Política de reduzir a pobreza sem confrontar o capital, em torno de Lula.', i='André Singer usou o termo para descrever a combinação de transferência de renda, salário mínimo e estabilidade econômica, com base entre os mais pobres e aliança com o centro.', e='Ativo nos programas sociais.', m='Mista, com estabilidade e bancos públicos.', d='Democrática, com acenos a governos autoritários de esquerda no exterior.', q='Redução gradual.', p='Estudado por André Singer.', h='Governos Lula, a partir de 2003, e sua volta em 2023.', b='É um fenômeno brasileiro.', pa=['pt'], fi=['Luiz Inácio Lula da Silva', 'Fernando Haddad'], c='A esquerda diz que é conciliação demais; a direita aponta corrupção, gastos e dependência em relação a um líder.', w='Lulismo', forte=['Reduziu a extrema pobreza e a fome.', 'Mostrou que dá para combinar programas sociais e estabilidade.'], contra=['Prega mudança e faz aliança com oligarquias.', 'Centrado em uma pessoa, em um partido que se diz coletivo.', 'Critica golpes aqui e relativiza ditaduras de esquerda fora.'], apelo=False),
